//! Generated bus reference and catalogue coverage gate (design §5.7).
//!
//! The source catalogue is deliberately simple: one macro invocation per
//! kind. Reading those rows here avoids linking the application bus into
//! the build tool, which would reverse the crate graph in design §4.1.
//! The source format is constrained intentionally: each kind is one macro
//! invocation with literal names and prose, while visibility and shape are
//! enum identifiers. A malformed edit fails this gate before docs are made.
//! The same pass checks enum coverage and generated bytes, so a new kind
//! cannot silently disappear from the public reference.
use std::{collections::BTreeSet, fs, path::Path};

/// One row of the source catalogue needed for reference generation.
struct Row {
    /// Rust variant checked against the closed enum.
    variant: String,
    /// Stable public protocol spelling.
    name: String,
    /// Whether the external boundary permits this row.
    visibility: String,
    /// Active kinds have real Rust variants; reserved names name a milestone.
    availability: String,
    /// Top-level shape validated by the current decoder.
    shape: String,
    /// Explanation shown to consumers of the protocol.
    description: String,
    /// Lane determines whether the operation can be dispatched.
    direction: &'static str,
}

/// Extracts catalogue rows without adding a TOML or Rust parser dependency.
fn rows() -> Result<Vec<Row>, String> {
    // Read the hand-maintained protocol table, which is the single source
    // for runtime lookup, documentation and the future JS type surface.
    let source = fs::read_to_string("crates/puzzle-term/src/messages/catalogue.rs")
        .map_err(|error| error.to_string())?;
    let mut result = Vec::new();
    for line in source.lines().map(str::trim) {
        // Ignore prose and macro definitions. Only invocation rows form
        // protocol entries, so comments cannot accidentally generate API.
        let direction = if line.starts_with("command!(\"") {
            "Command"
        } else if line.starts_with("event!(\"") {
            "Event"
        } else {
            continue;
        };
        // Literal fields are quoted; enum fields sit between name and prose.
        // A changed row layout is an error rather than an opportunity for
        // this lightweight reader to guess what the author intended.
        // Reserved statuses include a quoted milestone, so splitting on
        // quote characters would mistake it for a protocol field.
        let Some(start) = line.find('(') else {
            continue;
        };
        let Some(end) = line.rfind(')') else {
            continue;
        };
        // The parser respects quotes and parentheses but deliberately does
        // not accept arbitrary Rust expressions in catalogue rows.
        let args = split_arguments(&line[start + 1..end]);
        if args.len() != 6 {
            return Err(format!("malformed bus catalogue row: {line}"));
        }
        // Visibility is an explicit decision for each Rust variant (D-26).
        // A misspelling must never default a platform result to public.
        // A typo in either gate must fail generation; defaulting visibility
        // or availability could expose a future platform-only message.
        if !matches!(args[2].as_str(), "Public" | "Internal")
            || !(args[4] == "Active" || args[4].starts_with("Reserved(\"M"))
        {
            return Err(format!("invalid bus visibility or shape: {line}"));
        }
        result.push(Row {
            variant: args[0].trim_matches('"').into(),
            name: args[1].trim_matches('"').into(),
            visibility: args[2].clone(),
            shape: args[3].clone(),
            availability: args[4].clone(),
            description: args[5].trim_matches('"').into(),
            direction,
        });
    }
    Ok(result)
}

/// Splits macro arguments while preserving commas inside quoted descriptions.
fn split_arguments(input: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut start = 0;
    let mut quoted = false;
    let mut depth = 0_usize;
    // Track nested status parentheses so their syntax cannot split a row;
    // descriptions may also contain commas inside literal quotes.
    for (index, character) in input.char_indices() {
        match character {
            '"' => quoted = !quoted,
            '(' if !quoted => depth += 1,
            ')' if !quoted => depth = depth.saturating_sub(1),
            ',' if !quoted && depth == 0 => {
                result.push(input[start..index].trim().to_owned());
                start = index + 1;
            }
            _ => {}
        }
    }
    result.push(input[start..].trim().to_owned());
    result
}

/// Reads enum variants for comparison with the independently written table.
fn variants(source: &str, name: &str) -> BTreeSet<String> {
    // The scanner is limited to the simple closed enums in message.rs;
    // comparing two separately edited sources catches omitted catalogue rows.
    let mut inside = false;
    let mut fields = false;
    let mut found = BTreeSet::new();
    for line in source.lines().map(str::trim) {
        if line == format!("pub enum {name} {{") {
            // Ignore Origin and any future helper enum in the same module.
            inside = true;
        } else if inside && line == "}" && !fields {
            // The first closing brace ends this enum's variant list.
            break;
        } else if fields {
            // Named payload fields are documented items, not additional
            // bus variants. Stop at their closing brace, then resume the
            // enum's top-level variant inventory.
            if line.starts_with('}') {
                fields = false;
            }
        } else if inside && !line.starts_with("///") && !line.starts_with('#') {
            // Variants with tuple data and unit variants both begin with
            // the spelling that must occur in the protocol catalogue.
            let variant = line.split(['(', ',', '{']).next().unwrap_or("").trim();
            if !variant.is_empty() {
                found.insert(variant.into());
            }
            fields = line.ends_with('{');
        }
    }
    found
}

/// Fails if a built-in kind is missing, repeated, or lacks visibility.
pub(crate) fn check_catalogue() -> Result<(), String> {
    // Runtime mask indices follow enum order. Coverage here protects new
    // cases from becoming invisible at the external boundary.
    let source = fs::read_to_string("crates/puzzle-term/src/messages.rs")
        .map_err(|error| error.to_string())?;
    let all = rows()?;
    for name in ["Command", "Event"] {
        // A set detects omissions while the vector length also detects
        // duplicate rows with the same Rust variant spelling.
        // Only active rows require a present enum variant. Reserved rows
        // intentionally have no payload type until their named milestone.
        let expected = variants(&source, name);
        let actual = all
            .iter()
            .filter(|row| row.direction == name && row.availability == "Active")
            .map(|row| row.variant.clone())
            .collect::<Vec<_>>();
        let unique = actual.iter().cloned().collect::<BTreeSet<_>>();
        // Set equality catches missing rows; the length check catches two
        // rows that accidentally claim the same concrete Rust variant.
        if expected != unique || actual.len() != unique.len() {
            return Err(format!("{name} catalogue differs from enum variants"));
        }
    }
    // Built-in payloads must remain real Rust types (D-1). `Value` belongs
    // only to the wire conversion and the erased extension seam.
    // D-1 would be lost if a built-in variant accepted a generic `Value`;
    // refuse that spelling directly in the enum declaration.
    for name in ["Command", "Event"] {
        let mut inside = false;
        for line in source.lines().map(str::trim) {
            if line == format!("pub enum {name} {{") {
                inside = true;
                continue;
            }
            if inside && line == "}" {
                break;
            }
            if inside && !line.starts_with("///") && line.contains("Value") {
                return Err(format!("{name} built-in variant carries Value"));
            }
        }
    }
    let mut names = BTreeSet::new();
    // Commands and events may share a semantic name, but two names within
    // one lane would make external decoding ambiguous.
    for row in all
        .iter()
        .filter(|row| row.visibility == "Public" && row.variant != "Ext")
    {
        if !names.insert((&row.direction, &row.name)) {
            return Err(format!("duplicate public bus name: {}", row.name));
        }
        if !row.name.contains('/') || row.name.contains(' ') {
            // Public names remain slash-separated protocol identifiers;
            // changing their spelling would break recordings and plugins.
            return Err(format!("invalid bus name: {}", row.name));
        }
    }
    Ok(())
}

/// Renders the checked catalogue for JS and Rust API readers.
fn render() -> Result<(String, String), String> {
    // Never produce authoritative looking files from an incomplete table.
    check_catalogue()?;
    let all = rows()?;
    let mut markdown = String::from(
        "# Puzzle Terminal bus messages\n\nGenerated by `cargo xtask settings-docs` from `puzzle-term::messages` (design §5.7). Reserved names cannot be dispatched until their typed payload arrives.\n\n| Type | Direction | Visibility | Status | Payload | Meaning |\n|------|-----------|------------|--------|---------|---------|\n",
    );
    let mut types = String::from("// Generated by `cargo xtask settings-docs` from design §5.7.\n");
    // Separate command and fact unions prevent dispatching an event name.
    // M10's JS bindings will consume these declarations.
    for (direction, alias) in [("Command", "CommandType"), ("Event", "EventType")] {
        types.push_str(&format!("export type {alias} =\n"));
        for row in all.iter().filter(|row| {
            row.visibility == "Public" && row.availability == "Active" && row.direction == direction
        }) {
            // A template pattern represents any registered extension name.
            let token = if row.variant == "Ext" {
                "`ext:${string}/${string}`".to_owned()
            } else {
                format!("'{}'", row.name)
            };
            types.push_str(&format!("  | {token}\n"));
        }
        types.push_str("  ;\n");
    }
    // Documentation shows future and internal names for planning and audit;
    // runtime decoding still accepts only active public rows.
    for row in &all {
        // Reserved and internal rows are visible as reference entries,
        // while only active public names enter generated dispatch types.
        let status = if row.availability == "Active" {
            "active".to_owned()
        } else {
            format!(
                "reserved ({})",
                row.availability
                    .trim_start_matches("Reserved(\"")
                    .trim_end_matches("\")")
            )
        };
        markdown.push_str(&format!(
            "| `{}` | {} | {} | {} | {} | {} |\n",
            row.name, row.direction, row.visibility, status, row.shape, row.description
        ));
    }
    // These signatures prepare the stable surface without adding the M10
    // JavaScript runtime or claiming its methods are already available.
    types.push_str(
        "export interface BusMessage { type: CommandType | EventType; payload?: unknown }\n",
    );
    types.push_str("export interface BusValidationReport { issues: ReadonlyArray<{ path: string; message: string }> }\n");
    types.push_str("export interface BusDisposable { dispose(): void }\n");
    types.push_str("export interface BusAccess {\n  dispatch(action: { type: CommandType; payload?: unknown }): BusValidationReport;\n  subscribe(patterns: string | string[], cb: (msgs: BusMessage[]) => void): BusDisposable;\n}\n");
    Ok((markdown, types))
}

/// Writes the bus reference; settings-specific outputs arrive in M6.
pub(crate) fn run() -> Result<(), String> {
    // Creating only the generated paths keeps M6 settings outputs absent
    // until their schema source is implemented.
    let (markdown, types) = render()?;
    fs::create_dir_all("docs").map_err(|error| error.to_string())?;
    fs::create_dir_all("crates/puzzle-web/types").map_err(|error| error.to_string())?;
    fs::write("docs/BUS.md", markdown).map_err(|error| error.to_string())?;
    fs::write("crates/puzzle-web/types/bus.d.ts", types).map_err(|error| error.to_string())
}

/// Rejects stale generated files during every workspace check.
pub(crate) fn check_generated() -> Result<(), String> {
    // Byte equality catches hand edits as well as stale output after a
    // catalogue rename. Callers regenerate through settings-docs.
    let (markdown, types) = render()?;
    for (path, expected) in [
        ("docs/BUS.md", markdown),
        ("crates/puzzle-web/types/bus.d.ts", types),
    ] {
        if fs::read_to_string(Path::new(path)).map_err(|error| error.to_string())? != expected {
            return Err(format!("generated bus reference is stale: {path}"));
        }
    }
    Ok(())
}
